import {
  type Clock,
  type ConfigEvent,
  createMachine,
  defineMachine,
  type EffectHandle,
  type Machine,
  systemClock,
  type Transition,
  type TransitionList,
} from "@cssints/machine";
import { type MachineStore, createMachineStore } from "@cssints/machine/solid";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import {
  createContext,
  createEffect,
  createUniqueId,
  merge,
  omit,
  onCleanup,
  type Store,
  untrack,
  useContext,
} from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** How long a full open or close takes on the spec's five-point grid. */
export const DISCLOSURE_ANIMATED_DURATION = 200;
/** The window a burst of `pointerenter`/`pointerleave` coalesces in. */
export const DISCLOSURE_ANIMATED_DEBOUNCE = 120;

/** The box: the four states `specs/patterns/animation.qnt` calls `visual`. */
export type DisclosureAnimatedPhase = "closed" | "opening" | "open" | "closing";

/** The machine's context: the exposed intent, the settled state and the motion preference. */
export interface DisclosureAnimatedContext {
  /** What `aria-expanded` says, set the moment an intent arrives. */
  readonly logical: boolean;
  /** What the machine has settled at; only an effect's completion moves it. */
  readonly committed: "closed" | "open";
  /** `prefers-reduced-motion: reduce` (or the `reducedMotion` override): no transition is entered. */
  readonly reduced: boolean;
}

// a type alias, not an interface: `PayloadMap` is an index signature, and only an alias is assignable to one
type DisclosureAnimatedPayloads = {
  readonly open: undefined;
  readonly close: undefined;
  readonly toggle: undefined;
  readonly hover: { readonly open: boolean };
  readonly finish: { readonly id: number };
  readonly motion: { readonly reduced: boolean };
};

/** The machine's events: the protocol's own, not the DOM's. */
export type DisclosureAnimatedEvent =
  | { readonly type: "open" }
  | { readonly type: "close" }
  | { readonly type: "toggle" }
  | { readonly type: "hover"; readonly open: boolean }
  | { readonly type: "finish"; readonly id: number }
  | { readonly type: "motion"; readonly reduced: boolean };

type DisclosureMachine = Machine<
  DisclosureAnimatedContext,
  DisclosureAnimatedPhase,
  DisclosureAnimatedEvent
>;

type Config = ConfigEvent<DisclosureAnimatedPayloads>;

// An intent is one direction: a click, a controlled host's write, or a hover the window committed. The transition
// list is guarded on the intent's direction (`hover` carries its own open flag) and on reduced motion: with the
// preference on the box lands at the intent in the same step, and no effect is issued. A same-direction intent has
// no transition at all — the machine drops it, so the running effect is not cancelled and restarted.
const wants = (event: Config, open: boolean): boolean =>
  event.type !== "hover" || event.open === open;

const toward = (open: boolean): TransitionList<DisclosureAnimatedContext, Config> => [
  {
    guard: (context, event) => wants(event, open) && context.reduced,
    target: open ? "open" : "closed",
    assign: { logical: open, committed: open ? "open" : "closed" },
  },
  {
    guard: (_context, event) => wants(event, open),
    target: open ? "opening" : "closing",
    assign: { logical: open },
    effect: { type: "animate", to: open ? "open" : "closed" },
  },
];

// The preference moves while the box is still: keep it, nothing else changes.
const followMotion = (
  phase: DisclosureAnimatedPhase,
): Transition<DisclosureAnimatedContext, Config> => ({
  target: phase,
  assign: (context, event) => ({
    reduced: event.type === "motion" ? event.reduced : context.reduced,
  }),
});

// The preference turns on mid-flight: the effect is cancelled by leaving the state, the box lands at the intent.
const stopMotion = (target: "open" | "closed"): Transition<DisclosureAnimatedContext, Config> => ({
  target,
  guard: (_context, event) => event.type === "motion" && event.reduced,
  assign: { reduced: true, committed: target },
});

const settle = (target: "open" | "closed"): Transition<DisclosureAnimatedContext, Config> => ({
  target,
  assign: { committed: target },
});

// The start context carries the motion preference, so a reduced page never enters a transition even for its first intent:
// the machine starts reduced, rather than being told so in a write from the component's owned scope.
const disclosureDefinition = (reduced: boolean) =>
  defineMachine<DisclosureAnimatedPayloads>()({
    start: "closed",
    // the two ends, not `string`: the context's `committed` is the settled state, and `assign` writes either one
    initial: { logical: false, committed: "closed" as "open" | "closed", reduced },
    states: {
      closed: {
        on: {
          open: toward(true),
          toggle: toward(true),
          hover: toward(true),
          motion: followMotion("closed"),
        },
      },
      opening: {
        on: {
          close: toward(false),
          toggle: toward(false),
          hover: toward(false),
          finish: settle("open"),
          motion: stopMotion("open"),
        },
      },
      open: {
        on: {
          close: toward(false),
          toggle: toward(false),
          hover: toward(false),
          motion: followMotion("open"),
        },
      },
      closing: {
        on: {
          open: toward(true),
          toggle: toward(true),
          hover: toward(true),
          finish: settle("closed"),
          motion: stopMotion("closed"),
        },
      },
    },
  });

/** The primitive, once: a fixture reads the machine and the box's position; a page rarely does. */
export interface DisclosureAnimatedController {
  /** The machine: `getState()`, `send()`, the live effect handles. */
  readonly machine: DisclosureMachine;
  /** The machine as Solid's store: one write per transition, and a reader of a field re-runs only for that field. */
  readonly store: MachineStore<
    DisclosureAnimatedContext,
    DisclosureAnimatedPhase,
    DisclosureAnimatedEvent
  >;
  /** The box's position on the spec's five-point grid (0 closed .. 4 open), read from the running animation. */
  readonly progress: () => number;
  /** The intent a controlled host delivers: the machine starts after an intent is accepted. */
  readonly setOpen: (open: boolean) => void;
}

export interface DisclosureAnimatedProps {
  /** The motion preference; left out, `prefers-reduced-motion: reduce` is read once. */
  readonly reducedMotion?: boolean;
  /** Controlled: writing it delivers an intent, as a host that accepts every request would. */
  readonly open?: boolean;
  /** Every intent's accepted value, in the protocol's own words. */
  readonly onOpenChange?: (open: boolean) => void;
  /** The machine's clock; the system one by default, a fake one in a test. */
  readonly clock?: Clock;
  /**
   * Every animation the host starts, once — after the element's `animate` call, before it is read. A test pauses it and
   * steps the timeline; a host may retime it. Not called when the panel's element is not rendered.
   */
  readonly onAnimate?: (animation: Animation) => void;
  readonly class?: string;
  readonly children?: JSX.Element;
  /** The primitive, once: a scenario fixture needs it; a page rarely does. */
  readonly onReady?: (controller: DisclosureAnimatedController) => void;
}

export type DisclosureAnimatedTriggerPartProps = PartProps;

export interface DisclosureAnimatedTriggerProps extends Renderable<
  DisclosureAnimatedTriggerPartProps,
  void
> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DisclosureAnimatedContentState {
  readonly phase: () => DisclosureAnimatedPhase;
  readonly visible: () => boolean;
}

export interface DisclosureAnimatedContentProps extends Renderable<
  PartProps,
  DisclosureAnimatedContentState
> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

interface LiveAnimation {
  readonly handle: EffectHandle;
  readonly animation: Animation;
  readonly from: number;
  readonly to: number;
  readonly duration: number;
}

interface DisclosureAnimatedScope {
  readonly store: MachineStore<
    DisclosureAnimatedContext,
    DisclosureAnimatedPhase,
    DisclosureAnimatedEvent
  >;
  readonly view: Store<{ visible: boolean }>;
  readonly contentId: string;
  readonly attach: (element: HTMLElement | undefined) => void;
  readonly scheduleHover: (open: boolean) => void;
  readonly toggle: () => void;
}

const ScopeContext = createContext<DisclosureAnimatedScope>();

const rootClass = css.cn(css.display("flex"), css.flexDirection("column"), css.gap(t.space._2));

const triggerClass = css.cn(
  css.group(),
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.padding(t.space._2, 0),
  css.bg("transparent"),
  css.border("none"),
  css.color(t.color.text),
  css.fontSize(t.font.size),
  css.fontWeight("500"),
  css.cursor("pointer"),
  css.textAlign("left"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const chevronClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.transition("transform 120ms"),
  css.within(css.attr("aria-expanded", "true"))(css.transform("rotate(90deg)")),
);

// The resting look is the state's own end of the grid: closed and closing are collapsed, opening and open are not. The
// animation covers the way between them (and a finished one is cancelled in the same task that writes the next state), so
// the panel never paints a frame at the wrong end. The grid row is what a disclosure grows.
const contentClass = css.cn(
  css.display("grid"),
  css.gridTemplateRows("0fr"),
  css.opacity(0),
  css.overflow("hidden"),
  css.willChange("grid-template-rows, opacity"),
  css.color(t.color.muted),
  css.fontSize(t.font.size),
  css.attr("data-state", "opening")(css.gridTemplateRows("1fr"), css.opacity(1)),
  css.attr("data-state", "open")(css.gridTemplateRows("1fr"), css.opacity(1)),
);

const contentInnerClass = css.cn(
  css.minHeight("0"),
  css.overflow("hidden"),
  css.paddingBlockStart(t.space._2),
);

const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * A disclosure whose panel animates open and closed, on `@cssints/machine`: the protocol `specs/patterns/animation.qnt`
 * fixes, and the first component that runs it.
 *
 * The intents are the machine's, not a signal's: an intent that arrives during the opposite animation reverses from the
 * box's own position (the running animation's `currentTime` is read before it is cancelled), leaving a state cancels its
 * effect and a late completion carrying that effect's id is dropped, a burst of `pointerenter`/`pointerleave` is
 * debounced with the last intent kept, and `prefers-reduced-motion` lands an intent in one step. `data-state` is the
 * box's phase and `hidden` its visibility, both written from the same store flush, so the panel is never hidden while
 * painted. The progress is read from the animation's real `currentTime`, which is why the animation is linear: the
 * spec's five-point grid is a sample of the timeline, not of an easing curve.
 */
export const DisclosureAnimated = (props: DisclosureAnimatedProps): JSX.Element => {
  const initialReduced = untrack(() => props.reducedMotion) ?? prefersReducedMotion();
  const machine: DisclosureMachine = createMachine(disclosureDefinition(initialReduced), {
    clock: untrack(() => props.clock) ?? systemClock,
  });
  // `store.send` would start an optimistic action whose open transaction holds the committed store until the machine
  // settles. The panel's `data-state` is the machine's own transient phase (`opening`, not `open`), so it reads the
  // committed store; the spec's optimistic split is the context's `logical` against `committed`, which is exact without
  // the action. One `setState` per transition writes only the changed fields, so a reader of `phase` does not re-run when
  // `logical` changes.
  const store = createMachineStore(machine);
  const view = store.projection(
    (draft, state) => {
      draft.visible = state.phase !== "closed";
    },
    { visible: false },
  );

  const contentId = createUniqueId();
  let content: HTMLElement | undefined;
  /** The live animation, or `undefined` at rest (and for the instant between a cancel and its replacement). */
  let live: LiveAnimation | undefined;
  /** Where a cancelled animation stopped: the reversal's start. */
  let carried: number | undefined;
  /** The phase before the transition in progress (effects run before the transition listener). */
  let lastPhase: DisclosureAnimatedPhase = machine.getState().state;

  const fractionOf = (effect: LiveAnimation): number => {
    const time = Number(effect.animation.currentTime ?? 0);
    const ratio = effect.duration === 0 ? 0 : Math.min(1, Math.max(0, time / effect.duration));
    return effect.from + (effect.to - effect.from) * ratio;
  };

  const progress = (): number => {
    if (live === undefined) {
      return machine.getState().state === "open" ? 4 : 0;
    }
    return Math.min(4, Math.max(0, Math.floor(fractionOf(live) * 4 + 0.000001)));
  };

  machine.onTransition((record) => {
    lastPhase = record.to as DisclosureAnimatedPhase;
  });

  const offEffect = machine.onEffect((handle) => {
    const fromTransient = lastPhase === "opening" || lastPhase === "closing";
    const to = handle.spec.to === "open" ? 1 : 0;
    // a reversal keeps the box where it was; a start begins at the end the box is already at
    const from = fromTransient && carried !== undefined ? carried : to === 1 ? 0 : 1;
    carried = undefined;
    const element = content;
    if (element === undefined) {
      queueMicrotask(() => machine.send({ type: "finish", id: handle.id }));
      return;
    }
    // the box moves at a constant rate in the grid, so a quarter of the duration is one grid point; `fill: "none"`
    // because the panel's own state styling is the animation's end at either direction
    const duration = DISCLOSURE_ANIMATED_DURATION * Math.max(Math.abs(to - from), 0.25);
    const animation = element.animate(
      [
        {
          gridTemplateRows: `${from}fr`,
          opacity: from,
          transform: `translateY(${(1 - from) * -4}px)`,
        },
        { gridTemplateRows: `${to}fr`, opacity: to, transform: `translateY(${(1 - to) * -4}px)` },
      ],
      { duration, easing: "linear", fill: "none" },
    );
    // the driver that steps a frame a grid point needs the animation's own ends; the id is the least visible place
    animation.id = `${from}:${to}`;
    live = { handle, animation, from, to, duration };
    props.onAnimate?.(animation);
    const done = (): void => {
      if (live?.handle.id === handle.id) {
        live = undefined;
      }
      animation.cancel();
      // a completion, and a cancelled animation's own late one: the machine drops the latter by its id
      machine.send({ type: "finish", id: handle.id });
    };
    animation.finished.then(done, done);
  });

  const offCancel = machine.onCancel((handle) => {
    if (live?.handle.id !== handle.id) {
      return;
    }
    const cancelled = live;
    carried = fractionOf(cancelled);
    live = undefined;
    cancelled.animation.cancel();
  });

  const sendIntent = (event: DisclosureAnimatedEvent): void => {
    if (event.type !== "hover") {
      // a direct intent is the window's end: a pending hover cannot land after it
      machine.cancel("hover");
    }
    store.send(event);
  };

  const scheduleHover = (open: boolean): void => {
    store.send({ type: "hover", open }, { debounce: DISCLOSURE_ANIMATED_DEBOUNCE });
  };

  const setOpen = (open: boolean): void => {
    sendIntent({ type: open ? "open" : "close" });
  };

  let logical = machine.getState().context.logical;
  machine.onTransition(() => {
    const next = machine.getState().context.logical;
    if (next !== logical) {
      logical = next;
      props.onOpenChange?.(next);
    }
  });

  // A prop write is a host intent, and an effect runs in an owned scope where the store refuses a write: deliver it on the
  // next microtask, where it is a plain event like a click's. The read happens then, so a burst of prop writes coalesces
  // to the last one the machine has not already accepted.
  createEffect(
    () => props.reducedMotion,
    (reduced) => {
      queueMicrotask(() => {
        if (reduced !== undefined && reduced !== machine.getState().context.reduced) {
          machine.send({ type: "motion", reduced });
        }
      });
    },
  );
  createEffect(
    () => props.open,
    (open) => {
      queueMicrotask(() => {
        if (open !== undefined && open !== machine.getState().context.logical) {
          sendIntent({ type: open ? "open" : "close" });
        }
      });
    },
  );

  const controller: DisclosureAnimatedController = { machine, store, progress, setOpen };
  untrack(() => props.onReady)?.(controller);

  onCleanup(() => {
    offEffect();
    offCancel();
    machine.destroy();
  });

  const scope: DisclosureAnimatedScope = {
    store,
    view,
    contentId,
    attach: (element) => {
      content = element;
    },
    scheduleHover,
    toggle: () => sendIntent({ type: "toggle" }),
  };

  return (
    <ScopeContext value={scope}>
      <div data-part="root" class={css.cn(rootClass, props.class)}>
        {props.children}
      </div>
    </ScopeContext>
  );
};

/** The button that delivers the intent: a click toggles, and a burst of hover is the debounced window. */
export const DisclosureAnimatedTrigger = (props: DisclosureAnimatedTriggerProps): JSX.Element => {
  const scope = useContext(ScopeContext);
  const rest = omit(props, "render", "class", "children");
  const merged = merge(rest, () => ({
    type: "button" as const,
    "data-part": "trigger",
    get "aria-expanded"() {
      return scope.store.state.logical ? "true" : "false";
    },
    "aria-controls": scope.contentId,
    onClick: () => scope.toggle(),
    onPointerEnter: () => scope.scheduleHover(true),
    onPointerLeave: () => scope.scheduleHover(false),
    get class() {
      return css.cn(triggerClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <button {...part}>
      <span aria-hidden="true" class={chevronClass}>
        ▸
      </span>
      <span>{props.children}</span>
    </button>
  ));
};

/** The panel: `data-state` is the box and `hidden` its visibility, both from the same store frame. */
export const DisclosureAnimatedContent = (props: DisclosureAnimatedContentProps): JSX.Element => {
  const scope = useContext(ScopeContext);
  const rest = omit(props, "render", "class", "children");
  const state: DisclosureAnimatedContentState = {
    phase: () => scope.store.state.phase,
    visible: () => scope.view.visible,
  };
  const merged = merge(rest, () => ({
    id: scope.contentId,
    "data-part": "content",
    get "data-state"() {
      return scope.store.state.phase;
    },
    get hidden() {
      return !scope.view.visible;
    },
    ref: (element: HTMLDivElement) => {
      scope.attach(element);
    },
    get class() {
      return css.cn(contentClass, props.class);
    },
  }));
  return renderPart(props, merged, state, (part) => (
    <div {...part}>
      <div class={contentInnerClass}>{props.children}</div>
    </div>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import {
  DISCLOSURE_ANIMATED_DEBOUNCE,
  DisclosureAnimated,
  type DisclosureAnimatedController,
  DisclosureAnimatedContent,
  DisclosureAnimatedTrigger,
} from "./disclosure-animated.tsx";
import { createFakeClock } from "@cssints/machine";
import { type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { createSignal, flush } from "solid-js";
import { render } from "@solidjs/web";
import { type AnimationConfig } from "@cssints/apg-specs/patterns/animation.bridge";
import { type Mounted } from "./disclosure-animated-driver.ts";

/**
 * Mounts the styled animated disclosure for the scenario walk. The fake clock is the machine's: `debounce` advances it,
 * exactly as a pointer burst's window closes. `onAnimate` pauses every animation the host starts, so the test owns the
 * timeline and `frame` is a grid point rather than a guess at the browser's frame rate.
 */
export const mountDisclosureAnimated = (config: AnimationConfig): Mounted => {
  const root = document.createElement("div");
  // The walk reads attributes and animation time, never hit-testing. Parking the fixture outside the viewport keeps a real
  // pointer left by another test file's `user-event` from firing an unasked `pointerenter` at the trigger when it mounts.
  root.style.position = "fixed";
  root.style.insetBlockStart = "0";
  root.style.insetInlineStart = "-10000px";
  document.body.append(root);
  const clock = createFakeClock();
  const [reduced, setReduced] = createSignal(config.reducedMotion);
  let controller: DisclosureAnimatedController | undefined;

  const dispose = render(
    () => (
      <DisclosureAnimated
        clock={clock}
        reducedMotion={reduced()}
        onAnimate={(animation) => animation.pause()}
        onReady={(ready) => {
          controller = ready;
        }}
      >
        <DisclosureAnimatedTrigger>Shipping, returns and refunds</DisclosureAnimatedTrigger>
        <DisclosureAnimatedContent>
          A disclosure is one button and the panel it animates.
        </DisclosureAnimatedContent>
      </DisclosureAnimated>
    ),
    root,
  );
  flush();

  const api = (): DisclosureAnimatedController => {
    if (controller === undefined) {
      throw new Error("the disclosure did not report a controller");
    }
    return controller;
  };

  return {
    root,
    setProp: (name, value) => {
      switch (name) {
        case "open":
          api().setOpen(value === true);
          break;
        case "reducedMotion":
          setReduced(value === true);
          flush();
          break;
        default:
          throw new Unsupported(`prop ${name}`);
      }
    },
    value: () => {
      const state = api().machine.getState();
      return {
        open: state.context.logical,
        state: state.state,
        committed: state.context.committed,
        progress: api().progress(),
        optimistic: state.context.logical !== (state.context.committed === "open"),
      } satisfies Record<string, Json>;
    },
    finishStale: () => {
      // a completion carrying a handle the machine does not have: the late one of an effect it already cancelled
      api().machine.send({ type: "finish", id: -1 });
    },
    debounce: () => clock.advance(DISCLOSURE_ANIMATED_DEBOUNCE),
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";

/**
 * The DOM side of the animation spec's vocabulary. The user-level steps are real input (a click, the two pointer
 * events); the effect steps act on the animation the component really created: `finish` completes it, and `frame`
 * advances its paused timeline one point of the spec's five-point grid. Nothing here counts frames or keeps a second
 * copy of the phase: `value` reads the machine and the animation's own `currentTime`.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (a controlled host's intent, or the motion preference). */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** The spec's observable value: the phase, the split, and the box's position from real timing. */
  readonly value: () => Json;
  /** Deliver the completion of an effect that was cancelled: a `finish` carrying a dead handle id. */
  readonly finishStale: () => void;
  /** Fire the debounce window. */
  readonly debounce: () => void;
  readonly dispose: () => void;
}

// Solid's store writes land in its own schedule; a promise's completion (the animation's `finished`) is a microtask and
// the DOM write after it is another. Flush on both sides of the macrotask, so an observation is never read early.
const settle = async (): Promise<void> => {
  flush();
  await new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
  flush();
};

const BOOLEAN_ATTRS = new Set(["hidden"]);

const endsOf = (animation: Animation): { readonly from: number; readonly to: number } => {
  const [from = "0", to = "0"] = animation.id.split(":");
  return { from: Number(from), to: Number(to) };
};

const durationOf = (animation: Animation): number =>
  Number(animation.effect?.getTiming().duration ?? 0);

/**
 * One grid point of the animation's own timeline. The component animates linearly from the position the box is at, so a
 * quarter of the distance is a quarter of the animation, and the frame lands on the spec's grid. A zero-distance
 * reversal (the box is already at the end it is heading to) has no point to advance; its progress is the end.
 */
const advance = (animation: Animation): void => {
  animation.pause();
  const { from, to } = endsOf(animation);
  const duration = durationOf(animation);
  if (duration === 0 || from === to) {
    return;
  }
  const time = Number(animation.currentTime ?? 0);
  const fraction = from + (to - from) * Math.min(1, Math.max(0, time / duration));
  const grid = Math.min(4, Math.max(0, Math.floor(fraction * 4 + 0.000001))) / 4;
  const direction = to > from ? 1 : -1;
  const next = Math.min(1, Math.max(0, grid + direction * 0.25));
  animation.currentTime = ((next - from) / (to - from)) * duration;
};

export const domDriver = (mounted: Mounted): Driver => {
  const { root } = mounted;

  const elementsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = elementsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const content = (): HTMLElement => {
    const element = root.querySelector<HTMLElement>('[data-part="content"]');
    if (element === null) {
      throw new Unsupported("no content part");
    }
    return element;
  };

  const pointer = (element: HTMLElement, type: "pointerenter" | "pointerleave"): void => {
    // the two events do not bubble: the component listens on the trigger itself
    element.dispatchEvent(new PointerEvent(type, { bubbles: false, pointerType: "mouse" }));
  };

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "click":
          // a synthetic click, not a pointer: the protocol's click and the pointer plumbing are separate, and a real
          // pointer left over the next fixture's trigger would fire an unasked `pointerenter` at it
          elementOf(step.target ?? "trigger").click();
          break;
        case "pointerEnter":
          pointer(elementOf(step.target ?? "trigger"), "pointerenter");
          break;
        case "pointerLeave":
          pointer(elementOf(step.target ?? "trigger"), "pointerleave");
          break;
        case "debounce":
          mounted.debounce();
          break;
        case "frame":
          for (const animation of content().getAnimations()) {
            advance(animation);
          }
          break;
        case "finish":
          for (const animation of content().getAnimations()) {
            animation.finish();
          }
          break;
        case "finishStale":
          mounted.finishStale();
          break;
        case "prop":
          mounted.setProp(step.prop ?? "", step.value);
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      // the spec's own parts put no focus anywhere: the trigger is focused by the browser, not by the protocol
      focus: () => null,
      // the bridge's `visible` is empty; the panel's `hidden` is its own probed attribute
      visible: () => [],
      events: () => [],
      attr: (target, name) => {
        const element = elementOf(target);
        const value = element.getAttribute(name);
        if (name === "aria-controls" && value !== null) {
          // the bridge names the part, not its index: `content`, as `expect.attrs` writes it
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] ?? value;
        }
        if (value === "") {
          return BOOLEAN_ATTRS.has(name) ? "true" : value;
        }
        return value;
      },
      value: mounted.value,
    },
    dispose: mounted.dispose,
  };
};

import {
  type ScenarioConfig,
  differentialWalk,
  parseScenarioFile,
  replayScenario,
  specDriver,
} from "@cssints/apg-specs/scenario";
import {
  animationBridge,
  animationConfig,
  animationProbe,
  animationSteps,
} from "@cssints/apg-specs/patterns/animation.bridge";
import { decodeDefinition, makeReferenceModel } from "@quint-machine/core";
import { describe, it } from "vite-plus/test";
import scenarios from "@cssints/apg-specs/scenarios/patterns/animation.spec.json";
import definitionJson from "@cssints/apg-specs/patterns/animation.model.json";
import { domDriver } from "./disclosure-animated-driver.ts";
import { mountDisclosureAnimated } from "./disclosure-animated.fixture";

// The component's conformance is the animation spec: `specs/patterns/animation.qnt` is the protocol, its 15 scenarios
// replay through this DOM, and a differential walk compares the generated model with the component after every step.
// The model's `progress` is a five-point sample of an arbitrary frame; the driver pins the frame by advancing the paused
// animation exactly one point, so the value probe compares the same grid the model does.
const model = makeReferenceModel(decodeDefinition(definitionJson));

const dom = (config: ScenarioConfig) => domDriver(mountDisclosureAnimated(animationConfig(config)));

describe("DisclosureAnimated x the animation spec (real DOM)", () => {
  const file = parseScenarioFile(scenarios);
  for (const scenario of file.scenarios) {
    it(scenario.id, async (context) => {
      const result = await replayScenario(scenario, animationBridge, dom);
      if (result.status === "unsupported") {
        context.skip(result.reason);
      }
    });
  }
});

describe("DisclosureAnimated x the animation spec (differential walk)", () => {
  // Both configs are driveable: the preference is a mount prop, and the fake clock is the machine's. A config the driver
  // could not drive would be `Unsupported` here, with the reason, rather than silently compared against a different widget.
  const CONFIGS: ReadonlyArray<ScenarioConfig> = [
    { reducedMotion: false },
    { reducedMotion: true },
  ];
  for (const config of CONFIGS) {
    it(`matches the generated model for ${JSON.stringify(config)}`, async () => {
      await differentialWalk({
        alphabet: animationSteps,
        probe: animationProbe,
        makePair: () => Promise.resolve([specDriver(model, animationBridge, config), dom(config)]),
        runs: 15,
        steps: 25,
        seed: 7,
      });
    });
  }
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
